param([Parameter(Mandatory)][string]$LeaseFile,[Parameter(Mandatory)][string]$SignatureFile,[Parameter(Mandatory)][string]$TrustedPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedSigningKeyId,[Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedDeploymentId,[Parameter(Mandatory)][string]$SecretRoot)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$root=Assert-BackupPathOutsideRepository $SecretRoot 'SecretRoot';$file=[IO.Path]::GetFullPath($LeaseFile);$prefix=$root.TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;if(-not($file+[IO.Path]::DirectorySeparatorChar).StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Secret lease must be beneath SecretRoot'};$bytes=[IO.File]::ReadAllBytes($file);Test-BackupSignature $bytes ([IO.File]::ReadAllBytes([IO.Path]::GetFullPath($SignatureFile))) $TrustedPublicKeyFile 'Secret lease';$lease=$script:BackupRestoreUtf8.GetString($bytes)|ConvertFrom-Json -Depth 10 -DateKind String;$signer=Get-BackupKeyFingerprint $TrustedPublicKeyFile 'Secret lease' $false;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if($signer-ceq$release-or$lease.SchemaVersion-ne1-or$lease.Product-cne'ET.Server'-or$lease.ArtifactType-cne'SecretLease'-or$lease.LeaseId-cnotmatch'^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'-or[long]$lease.Generation-lt1-or[String]::IsNullOrWhiteSpace([string]$lease.Provider)-or([string]$lease.Provider).Length-gt128-or$lease.SigningKeyId-cne$ExpectedSigningKeyId-or$lease.SigningPublicKeySha256-cne$signer-or$lease.ReleaseSigningPublicKeySha256-cne$release-or$lease.DeploymentId-cne$ExpectedDeploymentId){throw 'Secret lease identity is invalid'};$issued=[DateTimeOffset]::Parse($lease.IssuedAtUtc);$expires=[DateTimeOffset]::Parse($lease.ExpiresAtUtc);$now=[DateTimeOffset]::UtcNow;if($issued-gt$now.AddMinutes(5)-or$expires-le$now-or$expires-le$issued-or($expires-$issued).TotalHours-gt24){throw 'Secret lease validity window is invalid'};$seen=@{};foreach($entry in @($lease.Secrets)){$secret=[IO.Path]::GetFullPath((Join-Path $root $entry.RelativePath));if(-not($secret+[IO.Path]::DirectorySeparatorChar).StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)-or$seen.ContainsKey($secret)-or-not(Test-Path $secret -PathType Leaf)){throw 'Secret lease inventory path is invalid'};$seen[$secret]=$true;$item=Get-Item $secret -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or$item.Length-le0-or$item.Length-gt1MB-or$item.Length-ne[long]$entry.Size-or(Get-FileHash $secret -Algorithm SHA256).Hash.ToLowerInvariant()-cne$entry.Sha256){throw 'Secret lease content does not match inventory'}};if($seen.Count-lt1-or$seen.Count-gt64){throw 'Secret lease inventory count is invalid'};[ordered]@{Passed=$true;LeaseId=$lease.LeaseId;DeploymentId=$lease.DeploymentId;Generation=$lease.Generation;ExpiresAtUtc=$lease.ExpiresAtUtc;Secrets=$seen.Count;LeaseSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json
